prompt_extraction.bloc_schema_specifique:
"caracteristiques_mission": {
  "typologie_mission": "audit, stratégie, accompagnement, expertise, AMO",
  "domaine_expertise": "juridique, organisation, finances, com, SI, etc.",
  "livrables_attendus": ["livrable 1", "livrable 2"],
  "duree_mission": "durée en mois",
  "jours_consultant_estimes": null,
  "methodologie_attendue": "Méthodologie de mission attendue (ex: 'phase de cadrage + ateliers thématiques + COMOP mensuels + COPIL trimestriel + restitution finale', 'audit documentaire + entretiens semi-directifs + benchmark + restitution'). null si non précisé.",
  "livrables_par_phase": [
    {
      "phase": "Ex: 'Phase 1 — Diagnostic', 'Phase 2 — Préconisations', 'Phase 3 — Restitution'",
      "livrables": ["Liste des livrables attendus pour cette phase"]
    }
  ],
  "jours_consultant_par_profil": [
    {
      "profil": "Ex: 'Consultant senior', 'Consultant junior', 'Expert thématique'",
      "nb_jours_min": null,
      "nb_jours_max": null
    }
  ],
  "accompagnement_apres": "Durée et nature du suivi post-livraison si précisé (ex: 'support 3 mois post-restitution', 'transfert de compétences sur 1 mois'). null sinon."
},
"profils_intervenants": {
  "description": "Profils requis pour la mission",
  "chef_de_mission": {
    "_commentaire": "Recopie le résumé brut du RC si présent ('Chef de mission expérimenté senior 10 ans...'). Sinon, structure ci-dessous.",
    "anciennete_min_annees": null,
    "secteur_experience": "Ex: 'secteur public collectivités territoriales', 'organisations publiques santé'",
    "taux_dedie_pct": null,
    "certifs_requises": []
  },
  "consultants": [
    {
      "profil": "Ex: 'Consultant senior', 'Consultant junior', 'Expert métier'",
      "nombre": null,
      "anciennete_min_annees": null
    }
  ]
},
"qualifications_conseil": {
  "opqcm": ["Qualifications OPQCM exigées (codes) le cas échéant. Liste vide sinon."],
  "certifications_methodologiques": ["Méthodes/certifications exigées si applicable (ex: \"PRINCE2\", \"SCRUM\", \"ITIL\", \"ISO 20000\")"],
  "ordre_profession": "Inscription ordinale exigée si applicable (ex: 'avocat inscrit au barreau', 'commissaire aux comptes inscrit'). null sinon."
}

